"""Avisos (G09 «Avisos y agenda», M10 / C05 «Notificaciones»).

* `Aviso`: one notice for one person. Generated by the system from what happens in the other
  modules (`origen = sistema`, unique `clave` per person so it never repeats), or one copy of a
  comunicado that Gerencia / Coordinación sent (`origen = comunicado`).
* `AvisoNota`: notes on an aviso («Agregar nota», G09).
* `Comunicado`: an announcement to some cargos, with priority and expiry; its copies are avisos and
  their `leido_at` are the read receipts.
* `AgendaItem`: «Mi agenda»: what someone scheduled to act on (from an aviso or by hand).
"""

import uuid
from datetime import date, datetime, time
from typing import Any

from sqlalchemy import (
    Boolean,
    Date,
    DateTime,
    ForeignKey,
    Index,
    String,
    Text,
    Time,
    UniqueConstraint,
    func,
)
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.db.base import Base, UUIDPrimaryKeyMixin
from app.models.user import User


class Comunicado(UUIDPrimaryKeyMixin, Base):
    __tablename__ = "comunicados"

    titulo: Mapped[str] = mapped_column(String(160))
    cuerpo: Mapped[str] = mapped_column(Text)
    prioridad: Mapped[str] = mapped_column(String(10), default="normal")  # normal · alta
    audiencia: Mapped[list[str]] = mapped_column(JSONB, default=list)  # cargo / grupo keys
    expira_el: Mapped[date | None] = mapped_column(Date)
    creado_por_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("users.id", ondelete="SET NULL")
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.clock_timestamp(), nullable=False
    )

    creado_por: Mapped[User | None] = relationship(lazy="joined")


class Aviso(UUIDPrimaryKeyMixin, Base):
    __tablename__ = "avisos"
    __table_args__ = (
        UniqueConstraint("destinatario_id", "clave", name="clave"),
        Index("ix_avisos_destinatario_estado", "destinatario_id", "estado"),
    )

    destinatario_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("users.id", ondelete="CASCADE"), index=True
    )
    origen: Mapped[str] = mapped_column(String(12), default="sistema")  # sistema · comunicado
    tipo: Mapped[str] = mapped_column(String(40))  # «lead_sin_responsable», «comunicado»…
    tipo_txt: Mapped[str] = mapped_column(String(60))  # chip text
    nivel: Mapped[str] = mapped_column(String(8), default="info")  # bad · warn · info · gray
    clave: Mapped[str | None] = mapped_column(String(120))  # the event; NULL for comunicados
    titulo: Mapped[str] = mapped_column(String(300))
    detalle: Mapped[str | None] = mapped_column(Text)
    que_hacer: Mapped[str | None] = mapped_column(String(300))
    limite_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    link: Mapped[str | None] = mapped_column(String(200))
    accion_txt: Mapped[str | None] = mapped_column(String(60))
    datos: Mapped[list[dict[str, Any]]] = mapped_column(JSONB, default=list)  # G09's boxes
    requiere_accion: Mapped[bool] = mapped_column(Boolean, default=True)  # False: «Resumen del día»
    estado: Mapped[str] = mapped_column(String(12), default="por_atender")  # · atendido
    atendido_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    atendido_por_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("users.id", ondelete="SET NULL")
    )
    resuelto_auto: Mapped[bool] = mapped_column(Boolean, default=False)
    leido_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    comunicado_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("comunicados.id", ondelete="CASCADE"), index=True
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.clock_timestamp(), nullable=False
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), onupdate=func.now(), nullable=False
    )

    destinatario: Mapped[User] = relationship(foreign_keys=[destinatario_id], lazy="joined")
    atendido_por: Mapped[User | None] = relationship(foreign_keys=[atendido_por_id], lazy="joined")
    comunicado: Mapped[Comunicado | None] = relationship(lazy="joined")
    notas: Mapped[list["AvisoNota"]] = relationship(
        order_by="AvisoNota.created_at", lazy="selectin", cascade="all, delete-orphan"
    )


class AvisoNota(UUIDPrimaryKeyMixin, Base):
    __tablename__ = "aviso_notas"

    aviso_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("avisos.id", ondelete="CASCADE"), index=True
    )
    autor_id: Mapped[uuid.UUID | None] = mapped_column(ForeignKey("users.id", ondelete="SET NULL"))
    texto: Mapped[str] = mapped_column(String(1000))
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.clock_timestamp(), nullable=False
    )

    autor: Mapped[User | None] = relationship(lazy="joined")


class AgendaItem(UUIDPrimaryKeyMixin, Base):
    """An activity added by hand to someone's agenda (G09, G-088, G-089).

    `user_id` is whose agenda it is; `creado_por_id` who put it there. What someone else assigned
    can't be deleted by the owner: it's done, rejected or justified with a reason. Deleting (only
    what you put) keeps the row with `eliminado_at` for «Actividades eliminadas».
    """

    __tablename__ = "agenda_items"

    user_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("users.id", ondelete="CASCADE"), index=True
    )
    creado_por_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("users.id", ondelete="SET NULL")
    )
    fecha: Mapped[date] = mapped_column(Date, index=True)
    hora: Mapped[time | None] = mapped_column(Time)
    titulo: Mapped[str] = mapped_column(String(200))
    nota: Mapped[str | None] = mapped_column(String(500))
    prioridad: Mapped[str] = mapped_column(String(10), default="normal")  # normal · alta
    # pendiente · hecha · rechazada · justificada («atrasada» is derived)
    estado: Mapped[str] = mapped_column(String(12), default="pendiente")
    hecha_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    motivo: Mapped[str | None] = mapped_column(String(500))  # rechazo / justificación
    respondida_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    aviso_id: Mapped[uuid.UUID | None] = mapped_column(ForeignKey("avisos.id", ondelete="SET NULL"))
    eliminado_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    eliminado_por_id: Mapped[uuid.UUID | None] = mapped_column(
        ForeignKey("users.id", ondelete="SET NULL")
    )
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.clock_timestamp(), nullable=False
    )

    user: Mapped[User] = relationship(foreign_keys=[user_id], lazy="joined")
    creado_por: Mapped[User | None] = relationship(foreign_keys=[creado_por_id], lazy="joined")
    eliminado_por: Mapped[User | None] = relationship(
        foreign_keys=[eliminado_por_id], lazy="joined"
    )
    aviso: Mapped[Aviso | None] = relationship(lazy="joined")
